        cues: [
          { start: 147087, end: 149566, text: 'Good evening.King\'s Restaurant.', speaker: 'WOMAN' },
          {
            start: 149566,
            end: 154528,
            text: 'Good evening.I\'m ringing about the job I understand you have vacant.',
            speaker: 'MAN',
          },
          { start: 154528, end: 155295, text: 'Oh yes', speaker: 'WOMAN' },
          { start: 155295, end: 158006, text: 'I\'d like to find out a few more details,if i may.', speaker: 'MAN' },
          { start: 158006, end: 158106, text: 'Yes,of course.Can i take your name?', speaker: 'WOMAN' },
          { start: 160146, end: 162027, text: 'It\'s Peter Chin.', speaker: 'MAN' },
          {
            start: 162027,
            end: 170556,
            text: 'Okay Peter.Well,if you want to ask about the job and then if we\'re both still interested, we could arrange for you to come for an interview.',
            speaker: 'WOMAN',
          },
          {
            start: 170556,
            end: 177072,
            text: 'Great,thanks.I\'m afraid i missed the advert for the job but heard about it from a friend.',
            speaker: 'MAN',
          },
          { start: 177072, end: 180145, text: 'That\'s no problem at all.What would you like to know?', speaker: 'WOMAN' },
          { start: 180145, end: 184335, text: 'Well,um,what sort of work is it - washing up?', speaker: 'MAN' },
          { start: 184335, end: 186312, text: 'It\'s answering the phone.', speaker: 'WOMAN' },
          { start: 186312, end: 188667, text: 'Oh right,fine.', speaker: 'MAN' },
          { start: 188667, end: 191299, text: 'And not waiting at table.', speaker: 'WOMAN' },
          { start: 191299, end: 195707, text: 'That\'d be good.And how many nights a week would it be?', speaker: 'MAN' },
          { start: 195707, end: 198564, text: 'Well,we\'re really only busy at the weekend.', speaker: 'WOMAN' },
          { start: 198564, end: 200518, text: 'So two nights?', speaker: 'MAN' },
          { start: 200518, end: 204598, text: 'Three actually,so it would work out at twelve hours a week.', speaker: 'WOMAN' },
          { start: 204598, end: 207720, text: 'That\'d be fine.It wouldn\'t interfere with my studies.', speaker: 'MAN' },
          { start: 207720, end: 209000, text: 'Are you at the university?', speaker: 'WOMAN' },
          { start: 209232, end: 211317, text: 'Yes.First year Physics student.', speaker: 'MAN' },
          { start: 211317, end: 212255, text: 'On.right.', speaker: 'WOMAN' },
          {
            start: 212255,
            end: 218033,
            text: 'Um,and because i\'m not an EU national would i need a work permit?',
            speaker: 'MAN',
          },
          { start: 218033, end: 220965, text: 'Yes you would. Just get your tutor to sign it.', speaker: 'WOMAN' },
          {
            start: 220965,
            end: 227390,
            text: 'That wouldn\'t be a problem,if i were to get the job.Um,where exactly is the restaurant?',
            speaker: 'MAN',
          },
          {
            start: 227390,
            end: 233104,
            text: 'Well,we have two branches - the one we\'re recruiting for is in Hillsdunne Road.',
            speaker: 'WOMAN',
          },
          { start: 233104, end: 237000, text: 'I don\'t know that.How do you spell it please?', speaker: 'MAN' },
          { start: 237350, end: 243000, text: 'It\'s H-I-double L-S-D-U-double N-E Road.', speaker: 'WOMAN' },
          { start: 243821, end: 248592, text: 'Got that.Thanks.is it near a bus stop?', speaker: 'MAN' },
          {
            start: 248592,
            end: 252297,
            text: 'Yes. The nearest one would probably be just beside the Library.',
            speaker: 'WOMAN',
          },
          {
            start: 252297,
            end: 258549,
            text: 'Oh yes,i know it.That\'d be fine for me.And could i ask about the pay?',
            speaker: 'MAN',
          },
          { start: 258549, end: 261567, text: 'We\'re offering￡4.45 an hour.', speaker: 'WOMAN' },
          { start: 261567, end: 265666, text: 'That\'s very good.My last job was ￡3.95 an hour.', speaker: 'MAN' },
          {
            start: 265666,
            end: 317000,
            text: 'We feel it\'s pretty good and we also offer some good fringe benefits.',
            speaker: 'WOMAN',
          },
          { start: 317983, end: 318726, text: 'Really?', speaker: 'MAN' },
          { start: 318726, end: 321723, text: 'Well,we give you a free dinner,so you eat well.', speaker: 'WOMAN' },
          { start: 321723, end: 324259, text: 'Right,better than hostel food!', speaker: 'MAN' },
          {
            start: 324259,
            end: 329729,
            text: 'We certainly hope so! And we also offer extra pay for working on national holidays.',
            speaker: 'WOMAN',
          },
          { start: 329729, end: 331855, text: 'Oh,that\'s a really good perk,isn\'t it?', speaker: 'MAN' },
          {
            start: 331855,
            end: 339399,
            text: 'Yes,we think so.And then because of the difficulties of getting public transport, if you\'re working after 11 o\'clock we drive you home.',
            speaker: 'WOMAN',
          },
          { start: 339399, end: 341068, text: 'Oh,that\'s good to know.', speaker: 'MAN' },
          {
            start: 341068,
            end: 346536,
            text: 'well,we\'d certainly be interested in inviting you for an interview,if you\'re still interested?',
            speaker: 'WOMAN',
          },
          {
            start: 346536,
            end: 352678,
            text: 'Oh yes,certainly.Could I just also ask what qualities you\'re looking for?',
            speaker: 'MAN',
          },
          {
            start: 352678,
            end: 359278,
            text: 'Well,for this particular job we want a clear voice,which you obviously do have!',
            speaker: 'WOMAN',
          },
          { start: 359278, end: 361351, text: 'Thank.', speaker: 'MAN' },
          { start: 361351, end: 364330, text: 'And you must be able to think quickly,you know.', speaker: 'WOMAN' },
          { start: 364330, end: 366050, text: 'Well,i hope i\'d...', speaker: 'MAN' },
          {
            start: 366050,
            end: 370996,
            text: 'So,when could you come in for an interview?We\'re actually quite quiet tonight?',
            speaker: 'WOMAN',
          },
          {
            start: 370996,
            end: 379377,
            text: 'Sorry,I couldn\'t come tonight.Or tomorrow,I\'m afraid.Thursday\'s okay that\'d be 22nd of October.',
            speaker: 'MAN',
          },
          { start: 379377, end: 381263, text: 'Fine,after 5 p.m.?', speaker: 'WOMAN' },
          { start: 381263, end: 384471, text: 'Yes,fine.Would 6 o\'clock be okay?', speaker: 'MAN' },
          { start: 384471, end: 388578, text: 'Perfect.And could you bring along the names of two referees?', speaker: 'WOMAN' },
          { start: 388578, end: 390541, text: 'Yes,that\'s fine,no problem.', speaker: 'MAN' },
          { start: 390541, end: 392868, text: 'Good,I look forward to seeing you.', speaker: 'WOMAN' },
          { start: 392868, end: 396249, text: 'Oh,by the way,who should i ask for?', speaker: 'MAN' },
          { start: 396249, end: 400033, text: 'Oh yes ,of course,sorry.My name is Samira Manuja.', speaker: 'WOMAN' },
          { start: 400033, end: 402397, text: 'Can you spell that,please?', speaker: 'MAN' },
          { start: 402397, end: 406297, text: 'M-A-N-U-J-A.', speaker: 'WOMAN' },
          { start: 406297, end: 410619, text: 'Okay.i\'ve got that.Thanks very much.', speaker: 'MAN' },
          { start: 410619, end: 412094, text: 'Look forward to seeing you...', speaker: 'WOMAN' },
        ],
