        cues: [
          {
            start: 65081,
            end: 71994,
            text: 'So, Michelle, shall we make a start on our presentation? We haven\'t got that much time left.',
            speaker: 'ADAM',
          },
          {
            start: 71996,
            end: 81631,
            text: 'No, Adam. But at least we\'ve done all the background reading. I found it really interesting – I\'d never even heard of the Laki eruption before this.',
            speaker: 'MICHELLE',
          },
          { start: 81633, end: 86108, text: 'Me neither. I suppose 1783 is a long time ago.', speaker: 'ADAM' },
          {
            start: 86110,
            end: 91083,
            text: 'But it was a huge eruption and it had such devastating consequences.',
            speaker: 'MICHELLE',
          },
          {
            start: 91085,
            end: 105225,
            text: 'I know. It was great there were so many primary sources to look at. It really gives you a sense of how catastrophic the volcano was. People were really trying to make sense of the science for the first time.',
            speaker: 'ADAM',
          },
          {
            start: 105226,
            end: 116981,
            text: 'That\'s right. But what I found more significant was how it impacted directly and indirectly on political events, as well as having massive social and economic consequences.',
            speaker: 'MICHELLE',
          },
          { start: 116983, end: 121006, text: 'I know. That should be the main focus of our presentation.', speaker: 'ADAM' },
          {
            start: 121008,
            end: 134269,
            text: 'The observations made by people at the time were interesting, weren\'t they? I mean, they all gave a pretty consistent account of what happened, even if they didn\'t always use the same terminology.',
            speaker: 'MICHELLE',
          },
          {
            start: 134270,
            end: 143748,
            text: 'Yeah. I was surprised there were so many weather stations established by that time – so, you know, you can see how the weather changed, often by the hour.',
            speaker: 'ADAM',
          },
          {
            start: 143749,
            end: 163057,
            text: 'Right. Writers at the time talked about the Laki haze to describe the volcanic fog that spread across Europe. They all realised that this wasn\'t the sort of fog they were used to – and of course this was in pre-industrial times – so they hadn\'t experienced sulphur-smelling fog before.',
            speaker: 'MICHELLE',
          },
          { start: 163058, end: 164398, text: 'No, that\'s true.', speaker: 'ADAM' },
          {
            start: 164399,
            end: 176688,
            text: 'Reports from the period blamed the haze for an increase in headaches, respiratory issues and asthma attacks. And they all describe how it covered the sun and made it look a strange red colour.',
            speaker: 'MICHELLE',
          },
          { start: 176690, end: 179279, text: 'Must have been very weird.', speaker: 'ADAM' },
          {
            start: 179280,
            end: 189030,
            text: 'It\'s interesting that Benjamin Franklin wrote about the haze. Did you read that? He was the American ambassador in Paris at the time.',
            speaker: 'MICHELLE',
          },
          {
            start: 189031,
            end: 195270,
            text: 'Yeah. At first no one realised that the haze was caused by the volcanic eruption in Iceland.',
            speaker: 'ADAM',
          },
          {
            start: 195271,
            end: 199288,
            text: 'It was Benjamin Franklin who realised that before anyone else.',
            speaker: 'MICHELLE',
          },
          {
            start: 199290,
            end: 213087,
            text: 'He\'s often credited with that, apparently. But a French naturalist beat him to it – I can\'t remember his name. I\'d have to look it up. Then other naturalists had the same idea – all independently of each other.',
            speaker: 'ADAM',
          },
          {
            start: 213089,
            end: 224959,
            text: 'Oh right. We should talk about the immediate impact of the eruption, which was obviously enormous – especially in Iceland, where so many people died.',
            speaker: 'MICHELLE',
          },
          {
            start: 224961,
            end: 242072,
            text: 'Mmm. You\'d expect that – and the fact that the volcanic ash drifted so swiftly – but not that the effects would go on for so long. Or that two years after the eruption, strange weather events were being reported as far away as North America and North Africa.',
            speaker: 'ADAM',
          },
          {
            start: 242073,
            end: 255892,
            text: 'No. I found all that hard to believe too. It must have been terrible – and there was nothing anyone could do about it, even if they knew the ash cloud was coming in their direction.',
            speaker: 'MICHELLE',
          },
          {
            start: 291463,
            end: 300828,
            text: 'We should run through some of the terrible consequences of the eruption experienced in different countries. There\'s quite a varied range.',
            speaker: 'MICHELLE',
          },
          {
            start: 300830,
            end: 305861,
            text: 'Starting with Iceland, where the impact on farming was devastating.',
            speaker: 'ADAM',
          },
          {
            start: 305863,
            end: 320512,
            text: 'Mmm. One of the most dramatic things there was the effect on livestock as they grazed in the fields. They were poisoned because they ate vegetation that had been contaminated with fluorine as a result of the volcanic fallout.',
            speaker: 'MICHELLE',
          },
          {
            start: 320514,
            end: 332040,
            text: 'That was horrible. In Egypt, the bizarre weather patterns led to a severe drought and as a result the Nile didn\'t flood, which meant the crops all failed.',
            speaker: 'ADAM',
          },
          {
            start: 332041,
            end: 342652,
            text: 'It\'s so far from where the eruption happened and yet the famine there led to more people dying than any other country. It was worse than the plague.',
            speaker: 'MICHELLE',
          },
          {
            start: 342654,
            end: 359608,
            text: 'OK. Then in the UK the mortality rate went up a lot – presumably from respiratory illnesses. According to one report it was about double the usual number and included an unusually high percentage of people under the age of 25.',
            speaker: 'ADAM',
          },
          {
            start: 359610,
            end: 377481,
            text: 'Mmm. I think people will be surprised to hear that the weather in the USA was badly affected too. George Washington even makes a note in his diary that they were snowbound until March in Virginia. That was before he became president.',
            speaker: 'MICHELLE',
          },
          {
            start: 377483,
            end: 382618,
            text: 'Yes, and there was ice floating down the Mississippi, which was unprecedented.',
            speaker: 'ADAM',
          },
          { start: 382620, end: 387694, text: 'Astonishing, really. Anyway, what do you think ...', speaker: 'MICHELLE' },
        ],
